package com.autumnharvestc.server.execution.notifications;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;
import com.autumnharvestc.server.store.IdGeneration;
@Repository
public class NotificationEventRepo {
    private final JdbcTemplate jdbc;private final IdGeneration ids;
    public NotificationEventRepo(JdbcTemplate jdbc,IdGeneration ids){this.jdbc=jdbc;this.ids=ids;}
    public void gate(){jdbc.queryForObject("SELECT id FROM execution_notification_gate WHERE id=1 FOR UPDATE",Long.class);}
    public record Source(long id,long workspace,long project,long schedule,String scheduleName,String projectName,String plannedAt,String notifications,String state,String summary,String report,String job,String execution,String revision,String snapshot,String reason,String observedAt,String originalSnapshot,String executionDefinition){}
    public List<Long> workspaces(int limit){return jdbc.query("SELECT workspace_id FROM (SELECT s.workspace_id FROM execution_schedules s WHERE s.enabled=FALSE AND s.paused_reason_code IS NOT NULL AND s.notification_pause_source_version>s.notification_processed_version UNION SELECT o.workspace_id FROM execution_schedule_occurrences o LEFT JOIN execution_jobs j ON j.id=o.job_id WHERE o.notification_processed_version=0 AND (o.state IN ('expired','skipped','rejected') OR (o.state='submitted' AND j.state='ended' AND j.execution_released=TRUE))) candidates ORDER BY workspace_id LIMIT ?",(r,n)->r.getLong(1),limit);}
    public List<Long> occurrenceCandidates(long ws,int limit){return jdbc.query("SELECT o.id FROM execution_schedule_occurrences o LEFT JOIN execution_jobs j ON j.id=o.job_id WHERE o.workspace_id=? AND o.notification_processed_version=0 AND (o.state IN ('expired','skipped','rejected') OR (o.state='submitted' AND j.state='ended' AND j.execution_released=TRUE)) ORDER BY o.id LIMIT ?",(r,n)->r.getLong(1),ws,limit);}
    public Optional<Source> occurrence(long id){
        var scopes=jdbc.query("SELECT project_id,schedule_id FROM execution_schedule_occurrences WHERE id=?",(r,n)->new long[]{r.getLong(1),r.getLong(2)},id);if(scopes.isEmpty())return Optional.empty();var scope=scopes.getFirst();
        jdbc.queryForList("SELECT id FROM projects WHERE id=? FOR UPDATE",scope[0]);jdbc.queryForList("SELECT id FROM execution_schedules WHERE id=? FOR UPDATE",scope[1]);jdbc.queryForList("SELECT id FROM execution_schedule_occurrences WHERE id=? FOR UPDATE",id);
        return jdbc.query("SELECT o.*,s.name,s.notifications_json,p.name AS project_name,j.summary_json,j.report_state,j.snapshot_id AS original_snapshot_id,r.snapshot_version,r.execution_json FROM execution_schedule_occurrences o JOIN execution_schedules s ON s.id=o.schedule_id JOIN execution_schedule_revisions r ON r.schedule_id=o.schedule_id AND r.revision=o.revision JOIN projects p ON p.id=o.project_id LEFT JOIN execution_jobs j ON j.id=o.job_id AND j.execution_id=o.execution_id AND j.workspace_id=o.workspace_id AND j.project_id=o.project_id AND j.submitted_by=o.subject_user_id AND j.schedule_occurrence_id=o.id AND j.schedule_id=o.schedule_id AND j.schedule_revision=o.revision WHERE o.id=? AND o.notification_processed_version=0 AND (o.state IN ('expired','skipped','rejected') OR (o.state='submitted' AND j.state='ended' AND j.execution_released=TRUE))",(r,n)->new Source(r.getLong("id"),r.getLong("workspace_id"),r.getLong("project_id"),r.getLong("schedule_id"),r.getString("name"),r.getString("project_name"),r.getObject("planned_at_utc",OffsetDateTime.class).toInstant().toString(),r.getString("notifications_json"),r.getString("state"),r.getString("summary_json"),r.getString("report_state"),r.getString("job_id"),r.getString("execution_id"),r.getString("revision"),r.getString("snapshot_version"),r.getString("reason_code"),r.getObject("observed_at_utc",OffsetDateTime.class).toInstant().toString(),r.getString("original_snapshot_id"),r.getString("execution_json")),id).stream().findFirst();
    }
    public List<Long> pausedCandidates(long ws,int limit){return jdbc.query("SELECT id FROM execution_schedules WHERE workspace_id=? AND enabled=FALSE AND paused_reason_code IS NOT NULL AND notification_pause_source_version>notification_processed_version ORDER BY id LIMIT ?",(r,n)->r.getLong(1),ws,limit);}
    public record Pause(long id,long workspace,long project,String name,String projectName,long version,String reason,String notifications){}
    public Optional<Pause> pause(long id){
        var projects=jdbc.query("SELECT project_id FROM execution_schedules WHERE id=?",(r,n)->r.getLong(1),id);if(projects.isEmpty())return Optional.empty();jdbc.queryForList("SELECT id FROM projects WHERE id=? FOR UPDATE",projects.getFirst());jdbc.queryForList("SELECT id FROM execution_schedules WHERE id=? FOR UPDATE",id);
        return jdbc.query("SELECT s.*,p.name AS project_name FROM execution_schedules s JOIN projects p ON p.id=s.project_id WHERE s.id=? AND s.enabled=FALSE AND s.paused_reason_code IS NOT NULL AND s.notification_pause_source_version>s.notification_processed_version",(r,n)->new Pause(r.getLong("id"),r.getLong("workspace_id"),r.getLong("project_id"),r.getString("name"),r.getString("project_name"),r.getLong("notification_pause_source_version"),r.getString("paused_reason_code"),r.getString("notifications_json")),id).stream().findFirst();
    }
    public void consumeOccurrence(long id){jdbc.update("UPDATE execution_schedule_occurrences SET notification_processed_version=1 WHERE id=?",id);}
    public void consumePause(Pause p){jdbc.update("UPDATE execution_schedules SET notification_processed_version=? WHERE id=?",p.version(),p.id());}
    public long create(long ws,long project,long schedule,String source,long version,String kind,String reason,boolean inApp,Instant now){
        if(ids.appAssigned()){long id=ids.nextId();jdbc.update("INSERT INTO execution_notification_events(id,workspace_id,project_id,schedule_id,source_id,source_version,event_kind,reason_code,in_app,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",id,ws,project,schedule,source,version,kind,reason,inApp,utc(now));return id;}
        var key=new GeneratedKeyHolder();jdbc.update(c->{var s=c.prepareStatement("INSERT INTO execution_notification_events(workspace_id,project_id,schedule_id,source_id,source_version,event_kind,reason_code,in_app,created_at) VALUES(?,?,?,?,?,?,?,?,?)",new String[]{"id"});s.setLong(1,ws);s.setLong(2,project);s.setLong(3,schedule);s.setString(4,source);s.setLong(5,version);s.setString(6,kind);s.setString(7,reason);s.setBoolean(8,inApp);s.setObject(9,utc(now));return s;},key);return Objects.requireNonNull(key.getKey()).longValue();
    }
    public void body(long id,String body){jdbc.update("UPDATE execution_notification_events SET body_json=? WHERE id=?",body,id);}
    public List<Map<String,Object>> list(long workspace){return jdbc.query("SELECT id,project_id,body_json FROM execution_notification_events WHERE workspace_id=? AND in_app=TRUE AND body_json IS NOT NULL ORDER BY id DESC LIMIT 100",(r,n)->Map.of("id",r.getString(1),"project",r.getLong(2),"body",r.getString(3)),workspace);}
    public List<Map<String,Object>> memberPage(long ws,long user,int limit,Long before){var args=new ArrayList<Object>(List.of(ws,user,user));if(before!=null)args.add(before);args.add(limit);return jdbc.query("SELECT e.id,e.project_id,e.body_json FROM execution_notification_events e WHERE e.workspace_id=? AND e.in_app=TRUE AND e.body_json IS NOT NULL AND EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=e.workspace_id AND m.user_id=?) AND NOT EXISTS(SELECT 1 FROM project_acl a WHERE a.workspace_id=e.workspace_id AND a.project_id=e.project_id AND a.user_id=? AND a.role='NONE')"+(before==null?"":" AND e.id<?")+" ORDER BY e.id DESC LIMIT ?",(r,n)->Map.of("id",r.getString(1),"project",r.getLong(2),"body",r.getString(3)),args.toArray());}
    public Optional<Map<String,Object>> readable(long ws,long id){return jdbc.query("SELECT id,project_id,body_json FROM execution_notification_events WHERE workspace_id=? AND id=? AND in_app=TRUE AND body_json IS NOT NULL",(r,n)->Map.<String,Object>of("id",r.getString(1),"project",r.getLong(2),"body",r.getString(3)),ws,id).stream().findFirst();}
    public record Head(long id,String source,String version,String kind,String reason,String created,String detailState,boolean inApp){}
    public boolean scheduleExists(long ws,long project,long schedule){return jdbc.queryForObject("SELECT COUNT(*) FROM execution_schedules WHERE workspace_id=? AND project_id=? AND id=?",Long.class,ws,project,schedule)==1;}
    public List<Head> history(long ws,long project,long schedule,int limit,Long before){var args=new ArrayList<Object>(List.of(ws,project,schedule));if(before!=null)args.add(before);args.add(limit);return jdbc.query("SELECT id,source_id,source_version,event_kind,reason_code,created_at,in_app,CASE WHEN body_json IS NULL THEN 'expired' ELSE 'available' END AS detail_state FROM execution_notification_events WHERE workspace_id=? AND project_id=? AND schedule_id=?"+(before==null?"":" AND id<?")+" ORDER BY id DESC LIMIT ?",(r,n)->new Head(r.getLong("id"),r.getString("source_id"),r.getString("source_version"),r.getString("event_kind"),r.getString("reason_code"),r.getObject("created_at",OffsetDateTime.class).toInstant().toString(),r.getString("detail_state"),r.getBoolean("in_app")),args.toArray());}
    public record ObservationRow(long id,NotificationDtos.SourceObservation view){}
    private NotificationDtos.SourceObservation observation(long ws,long project,long schedule,String source,Long version,boolean consumed,boolean ready){
        if(version==null)return new NotificationDtos.SourceObservation(source,null,"unknown",null,null);
        if(!ready||!consumed)return new NotificationDtos.SourceObservation(source,String.valueOf(version),ready?"not-observed":"not-ready",null,null);
        return jdbc.query("SELECT id,in_app FROM execution_notification_events WHERE workspace_id=? AND project_id=? AND schedule_id=? AND source_id=? AND source_version=? ORDER BY id DESC LIMIT 1",(r,n)->new NotificationDtos.SourceObservation(source,String.valueOf(version),"recorded",r.getString("id"),r.getBoolean("in_app")),ws,project,schedule,source,version).stream().findFirst().orElseGet(()->new NotificationDtos.SourceObservation(source,String.valueOf(version),"not-selected",null,null));
    }
    /** Scope-authorized plain reads only; safe even while the caller holds the original project lock. */
    public List<ObservationRow> observations(long ws,long project,long schedule,int limit,Long before){
        var args=new ArrayList<Object>(List.of(ws,project,schedule));if(before!=null)args.add(before);args.add(limit);
        var rows=jdbc.query("SELECT o.id,o.notification_processed_version,(o.state IN ('expired','skipped','rejected') OR (o.state='submitted' AND EXISTS(SELECT 1 FROM execution_jobs j WHERE j.id=o.job_id AND j.execution_id=o.execution_id AND j.workspace_id=o.workspace_id AND j.project_id=o.project_id AND j.submitted_by=o.subject_user_id AND j.schedule_occurrence_id=o.id AND j.schedule_id=o.schedule_id AND j.schedule_revision=o.revision AND j.state='ended' AND j.execution_released=TRUE))) AS ready FROM execution_schedule_occurrences o WHERE o.workspace_id=? AND o.project_id=? AND o.schedule_id=?"+(before==null?"":" AND o.id<?")+" ORDER BY o.id DESC LIMIT ?",(r,n)->new Object[]{r.getLong("id"),r.getLong("notification_processed_version")==1,r.getBoolean("ready")},args.toArray());
        return rows.stream().map(r->new ObservationRow((Long)r[0],observation(ws,project,schedule,"occurrence/"+r[0],1L,(Boolean)r[1],(Boolean)r[2]))).toList();
    }
    public NotificationDtos.SourceObservation pauseObservation(long ws,long project,long schedule){return jdbc.query("SELECT notification_pause_source_version,notification_processed_version FROM execution_schedules WHERE workspace_id=? AND project_id=? AND id=? AND enabled=FALSE AND paused_reason_code IS NOT NULL",(r,n)->{Long version=(Long)r.getObject("notification_pause_source_version");return observation(ws,project,schedule,"schedule/"+schedule,version,version!=null&&r.getLong("notification_processed_version")>=version,true);},ws,project,schedule).stream().findFirst().orElse(null);}
    public boolean read(long event,long user){return jdbc.queryForObject("SELECT COUNT(*) FROM execution_notification_reads WHERE event_id=? AND user_id=?",Long.class,event,user)>0;}
    public void markRead(long event,long user){gate();if(!read(event,user))jdbc.update("INSERT INTO execution_notification_reads(event_id,user_id) VALUES(?,?)",event,user);}
    static OffsetDateTime utc(Instant now){return now.atOffset(ZoneOffset.UTC);}
}
